/// <summary>
/// Return TAMRebateTable record from TAMRebateTrans
/// </summary>
/// <param name = "_forUpdate">Select for update</param>
/// <returns><c>TAMRebateTable</c> record</returns>
public TAMRebateTable METTAMRebateTable(boolean _forUpdate = false)
{
    return TAMRebateTable::find(this.RebateId, _forUpdate);
}
